## QUIZ SUBMISSION EVENT FLOW

```typescript
// app/routes/api.quiz.$slug.submit.tsx
// Complete event emission on quiz submission:

export async function action({ request, params }: ActionFunctionArgs) {
  // ... parse and validate submission ...

  const sessionId = body.sessionId ?? crypto.randomUUID();

  // Emit quiz_completed event
  await trackEvent({
    shop,
    quizId: quiz.id,
    eventType: "quiz_completed",
    sessionId,
    data: {
      resultPageId: matchedResultPage.id,
      resultPageTitle: matchedResultPage.title,
      score,
      questionCount: questions.length,
      source: body.source ?? "embed",
      deviceType: body.deviceType ?? "desktop",
    },
  });

  // Update denormalized quiz counters
  await db.quiz.update({
    where: { id: quiz.id },
    data: {
      completions: { increment: 1 },
    },
  });

  return json({ resultPage: matchedResultPage, sessionId }, { headers: CORS_HEADERS });
}
```

