## QUESTION ANSWERED EVENT (Storefront Widget)

```typescript
// Called from storefront widget JS (extensions/quiz-widget/assets/quiz-widget.js)
// Batched via fetch to public API:

async function trackQuestionAnswered(quizId, questionId, answerId, sessionId, position) {
  // Non-blocking — fire and forget
  fetch(`/api/quiz/${quizSlug}/events`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      shop,
      eventType: "question_answered",
      sessionId,
      data: { questionId, answerId, questionPosition: position },
    }),
  }).catch(() => {}); // Silently ignore tracking failures
}
```

---

## ANALYTICS AGGREGATION QUERIES

```typescript
// app/services/analytics.server.ts

// ── Quiz funnel (starts → completions per question) ───────────────────────────
export async function getQuizFunnel(
  shop: string,
  quizId: string,
  dateRange: { from: Date; to: Date }
) {
  const [starts, questionEvents, completions] = await db.$transaction([
    // Total starts
    db.analyticsEvent.count({
      where: {
        shop, quizId,
        eventType: "quiz_started",
        createdAt: { gte: dateRange.from, lte: dateRange.to },
      },
    }),
    // Questions answered — group by question position
    db.analyticsEvent.findMany({
      where: {
        shop, quizId,
        eventType: "question_answered",
        createdAt: { gte: dateRange.from, lte: dateRange.to },
      },
      select: { data: true },
    }),
    // Completions
    db.analyticsEvent.count({
      where: {
        shop, quizId,
        eventType: "quiz_completed",
        createdAt: { gte: dateRange.from, lte: dateRange.to },
      },
    }),
  ]);

  return { starts, completions, completionRate: starts > 0 ? completions / starts : 0 };
}

// ── Revenue attribution ────────────────────────────────────────────────────────
export async function getRevenueAttribution(
  shop: string,
  quizId: string,
  dateRange: { from: Date; to: Date }
) {
  const result = await db.analyticsEvent.aggregate({
    where: {
      shop, quizId,
      eventType: "purchase",
      createdAt: { gte: dateRange.from, lte: dateRange.to },
    },
    _sum: { revenue: true },
    _count: { id: true },
  });

  return {
    totalRevenue: result._sum.revenue ?? 0,
    purchaseCount: result._count.id,
  };
}

// ── Daily completions for chart ────────────────────────────────────────────────
export async function getDailyCompletions(
  shop: string,
  quizId: string,
  days: number = 30
) {
  const from = new Date();
  from.setDate(from.getDate() - days);

  const events = await db.analyticsEvent.findMany({
    where: {
      shop, quizId,
      eventType: "quiz_completed",
      createdAt: { gte: from },
    },
    select: { createdAt: true },
    orderBy: { createdAt: "asc" },
  });

  // Group by date string
  const byDate: Record<string, number> = {};
  for (const event of events) {
    const date = event.createdAt.toISOString().split("T")[0];
    byDate[date] = (byDate[date] ?? 0) + 1;
  }

  return byDate;
}

// ── Top result pages ───────────────────────────────────────────────────────────
export async function getTopResultPages(
  shop: string,
  quizId: string,
  limit: number = 5
) {
  const events = await db.analyticsEvent.findMany({
    where: { shop, quizId, eventType: "quiz_completed" },
    select: { data: true },
  });

  const counts: Record<string, number> = {};
  for (const event of events) {
    try {
      const data = JSON.parse(event.data) as { resultPageTitle?: string };
      if (data.resultPageTitle) {
        counts[data.resultPageTitle] = (counts[data.resultPageTitle] ?? 0) + 1;
      }
    } catch {
      // Skip malformed data
    }
  }

  return Object.entries(counts)
    .sort(([, a], [, b]) => b - a)
    .slice(0, limit)
    .map(([title, count]) => ({ title, count }));
}
```

