# Error Boundaries Agent — React Error UI Specialist

You implement all error boundary components for QuizSnap. Every route file must export an `ErrorBoundary` component. You build error UIs using Polaris v13 components that match the embedded app context.

---

## AUTO-DETECT TRIGGERS

- "error boundary", "ErrorBoundary", "route error"
- "error page", "crash", "unhandled error", "error UI"
- "useRouteError", "isRouteErrorResponse"

---

## BASE ERROR BOUNDARY COMPONENT

```tsx
// app/components/shared/QuizSnapErrorBoundary.tsx
import { useRouteError, isRouteErrorResponse, Link } from "react-router";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  Text,
  Button,
  Banner,
  InlineStack,
} from "@shopify/polaris";

export function QuizSnapErrorBoundary() {
  const error = useRouteError();

  // ── Structured HTTP error (thrown from loader/action) ──────────────────────
  if (isRouteErrorResponse(error)) {
    if (error.status === 404) {
      return (
        <Page title="Not found" backAction={{ url: "/app", content: "Dashboard" }}>
          <Layout>
            <Layout.Section>
              <Card>
                <BlockStack gap="400">
                  <Text variant="headingLg" as="h2">Page not found</Text>
                  <Text as="p" tone="subdued">
                    {error.data?.error ?? "The page you're looking for doesn't exist."}
                  </Text>
                  <InlineStack gap="200">
                    <Button url="/app" variant="primary">Go to dashboard</Button>
                    <Button url="/app/quizzes">View quizzes</Button>
                  </InlineStack>
                </BlockStack>
              </Card>
            </Layout.Section>
          </Layout>
        </Page>
      );
    }

    if (error.status === 403) {
      return (
        <Page title="Access denied" backAction={{ url: "/app", content: "Dashboard" }}>
          <Layout>
            <Layout.Section>
              <Card>
                <BlockStack gap="400">
                  <Banner tone="critical" title="Access denied">
                    <p>You don't have permission to access this feature.</p>
                  </Banner>
                  <Text as="p" tone="subdued">
                    {error.data?.error ?? "This feature requires a higher plan."}
                  </Text>
                  <Button url="/app/billing" variant="primary">View plans</Button>
                </BlockStack>
              </Card>
            </Layout.Section>
          </Layout>
        </Page>
      );
    }

    // Generic HTTP error (400, 500, etc.)
    return (
      <Page title="Error" backAction={{ url: "/app", content: "Dashboard" }}>
        <Layout>
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <Text variant="headingLg" as="h2">
                  {error.status >= 500 ? "Something went wrong" : "Request failed"}
                </Text>
                <Text as="p" tone="subdued">
                  {error.data?.error ?? `Error ${error.status}: ${error.statusText}`}
                </Text>
                <InlineStack gap="200">
                  <Button url="/app">Go to dashboard</Button>
                  <Button onClick={() => window.location.reload()}>Try again</Button>
                </InlineStack>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>
      </Page>
    );
  }

  // ── Unexpected JavaScript error ────────────────────────────────────────────
  const message = error instanceof Error
    ? error.message
    : typeof error === "string"
      ? error
      : "An unexpected error occurred";

  return (
    <Page title="Unexpected error" backAction={{ url: "/app", content: "Dashboard" }}>
      <Layout>
        <Layout.Section>
          <Card>
            <BlockStack gap="400">
              <Text variant="headingLg" as="h2">Something went wrong</Text>
              <Text as="p" tone="subdued">{message}</Text>
              <InlineStack gap="200">
                <Button url="/app" variant="primary">Go to dashboard</Button>
                <Button onClick={() => window.history.back()}>Go back</Button>
              </InlineStack>
            </BlockStack>
          </Card>
        </Layout.Section>
      </Layout>
    </Page>
  );
}
```

---

## HOW TO ADD TO EVERY ROUTE FILE

```tsx
