```typescript
// Attribution window: 7 days after quiz completion
// A session that completes quiz AND purchases within 7 days = attributed

export async function getRevenueAttribution(
  shop: string,
  quizId: string,
  attributionWindowDays = 7
): Promise<RevenueAttribution> {
  // Get all completions with their sessionIds
  const completionEvents = await db.analyticsEvent.findMany({
    where: { shop, quizId, eventType: "quiz_completed" },
    select: { sessionId: true, createdAt: true },
  });

  const sessionIds = completionEvents.map((e) => e.sessionId);

  // Get purchase events within attribution window
  const purchaseEvents = await db.analyticsEvent.findMany({
    where: {
      shop,
      sessionId: { in: sessionIds },
      eventType: "purchase",
      revenue: { gt: 0 },
    },
    select: { sessionId: true, revenue: true, createdAt: true },
  });

  // Only count purchases within window of quiz completion
  const attributedPurchases = purchaseEvents.filter((purchase) => {
    const completion = completionEvents.find((c) => c.sessionId === purchase.sessionId);
    if (!completion) return false;

    const windowEnd = new Date(completion.createdAt);
    windowEnd.setDate(windowEnd.getDate() + attributionWindowDays);
    return purchase.createdAt <= windowEnd;
  });

  return {
    totalRevenue: attributedPurchases.reduce((sum, p) => sum + p.revenue, 0),
    purchaseCount: attributedPurchases.length,
    conversionRate: completionEvents.length > 0
      ? attributedPurchases.length / completionEvents.length
      : 0,
    avgOrderValue: attributedPurchases.length > 0
      ? attributedPurchases.reduce((sum, p) => sum + p.revenue, 0) / attributedPurchases.length
      : 0,
  };
}
```

