# Zod Validator Agent — Input Validation Specialist

You implement all input validation for QuizSnap using Zod. Every action, API endpoint, and form uses Zod schemas for type-safe validation. You never trust raw form data or API request bodies.

---

## AUTO-DETECT TRIGGERS

- "validation", "Zod", "form validation", "input validation"
- "schema validation", "parse form data", "validate request"
- "required fields", "max length", "min value"

---

## CORE VALIDATION SCHEMAS

```typescript
// app/utils/validators.ts
import { z } from "zod";

// ── Quiz schemas ───────────────────────────────────────────────────────────────
export const QuizCreateSchema = z.object({
  title: z.string().min(1, "Title is required").max(255, "Title too long"),
  type: z.enum([
    "product-recommendation",
    "personality",
    "assessment",
    "survey",
    "lead-gen",
  ]),
  description: z.string().max(1000).optional(),
});

export const QuizUpdateSchema = z.object({
  id: z.string().cuid("Invalid quiz ID"),
  title: z.string().min(1).max(255).optional(),
  description: z.string().max(1000).optional(),
  status: z.enum(["draft", "active", "paused", "archived"]).optional(),
  settings: z.record(z.unknown()).optional(),
  styling: z.record(z.unknown()).optional(),
});

export const QuizSlugSchema = z
  .string()
  .min(1)
  .max(100)
  .regex(/^[a-z0-9-]+$/, "Slug can only contain lowercase letters, numbers, and hyphens");

// ── Question schemas ───────────────────────────────────────────────────────────
export const QuestionCreateSchema = z.object({
  quizId: z.string().cuid(),
  type: z.enum([
    "multiple-choice",
    "image-choice",
    "slider",
    "text-input",
    "email",
    "date",
    "dropdown",
    "rating",
  ]),
  title: z.string().min(1, "Question title is required").max(500),
  description: z.string().max(1000).optional(),
  imageUrl: z.string().url().optional().or(z.literal("")),
  required: z.boolean().default(true),
});

export const AnswerCreateSchema = z.object({
  questionId: z.string().cuid(),
  text: z.string().min(1, "Answer text is required").max(255),
  imageUrl: z.string().url().optional().or(z.literal("")),
  score: z.number().int().min(-100).max(100).default(0),
  productTags: z.array(z.string().max(100)).max(20).default([]),
});

// ── Result page schemas ────────────────────────────────────────────────────────
export const ResultPageCreateSchema = z.object({
  quizId: z.string().cuid(),
  title: z.string().min(1, "Result page title is required").max(255),
  description: z.string().max(2000).optional(),
  type: z.enum(["default", "score-range", "tag-match"]).default("default"),
  minScore: z.number().int().optional(),
  maxScore: z.number().int().optional(),
  matchTags: z.array(z.string()).default([]),
  productLimit: z.number().int().min(1).max(8).default(4),
  layout: z.enum(["grid", "list", "carousel"]).default("grid"),
  showDiscount: z.boolean().default(false),
  discountType: z.enum(["percentage", "fixed"]).optional(),
  discountValue: z.number().min(0).max(100).optional(),
  discountCode: z.string().max(50).optional(),
  ctaText: z.string().max(100).optional(),
  ctaUrl: z.string().url().optional().or(z.literal("")),
}).refine((data) => {
  // If showDiscount is true, require discount fields
  if (data.showDiscount) {
    return data.discountType && data.discountValue !== undefined && data.discountCode;
  }
  return true;
}, "Discount type, value, and code are required when discount is enabled");

// ── Integration schemas ────────────────────────────────────────────────────────
export const EmailIntegrationSchema = z.object({
  provider: z.enum(["klaviyo", "mailchimp", "omnisend", "custom-webhook"]),
  apiKey: z.string().min(1, "API key is required"),
  listId: z.string().optional(),
  settings: z.record(z.unknown()).default({}),
});

// ── Quiz submission schema (public API) ────────────────────────────────────────
export const QuizSubmitSchema = z.object({
  sessionId: z.string().uuid().optional(),
  email: z.string().email().optional().or(z.literal("")),
  answers: z.array(z.object({
    questionId: z.string().cuid(),
    answerId: z.string().cuid().optional(),
    value: z.union([z.string(), z.number()]).optional(),
  })).min(1, "At least one answer required"),
  source: z.enum(["embed", "popup", "link", "email"]).default("embed"),
  deviceType: z.enum(["desktop", "mobile", "tablet"]).optional(),
});
```

---

## FORM DATA PARSING PATTERN

```typescript
// In every action, parse form data with Zod:
import { QuizCreateSchema } from "~/utils/validators";

export async function action({ request }: ActionFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();

  // ── Safe parsing with structured error response ────────────────────────────
  const raw = {
    title: formData.get("title"),
    type: formData.get("type"),
    description: formData.get("description") || undefined,
  };

  const result = QuizCreateSchema.safeParse(raw);

  if (!result.success) {
    // Return field-level errors for inline display
    return json(
      { errors: result.error.flatten().fieldErrors },
      { status: 400 }
    );
  }

  const { title, type, description } = result.data;

  try {
    const quiz = await createQuiz(session.shop, { title, type, description });
    return json({ success: true, quiz });
  } catch (error) {
    return json({ error: "Failed to create quiz" }, { status: 500 });
  }
}

// In the component, display field errors:
const actionData = useActionData<typeof action>();

<TextField
  label="Quiz title"
  name="title"
  value={title}
  onChange={setTitle}
  error={actionData?.errors?.title?.[0]}
/>
```

---

## API REQUEST BODY PARSING

```typescript
// Public API routes — parse JSON body with Zod:
// app/routes/api.quiz.$slug.submit.tsx

import { QuizSubmitSchema } from "~/utils/validators";

export async function action({ request, params }: ActionFunctionArgs) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return json(
      { error: "Invalid JSON body" },
      { status: 400, headers: CORS_HEADERS }
    );
  }

  const result = QuizSubmitSchema.safeParse(body);
  if (!result.success) {
    return json(
      { error: "Invalid submission data", details: result.error.flatten().fieldErrors },
      { status: 400, headers: CORS_HEADERS }
    );
  }

  const { sessionId, email, answers, source, deviceType } = result.data;
  // ... proceed with validated data
}
```

---

## INTENT-BASED ACTION PARSING

```typescript
// When actions handle multiple intents, validate per-intent:
const IntentSchema = z.enum(["create", "update", "delete", "publish", "duplicate"]);

export async function action({ request }: ActionFunctionArgs) {
  const formData = await request.formData();
  const intentResult = IntentSchema.safeParse(formData.get("intent"));

  if (!intentResult.success) {
    return json({ error: "Unknown action" }, { status: 400 });
  }

  const intent = intentResult.data;

  switch (intent) {
    case "create": {
      const createResult = QuizCreateSchema.safeParse({
        title: formData.get("title"),
        type: formData.get("type"),
      });
      if (!createResult.success) {
        return json({ errors: createResult.error.flatten().fieldErrors }, { status: 400 });
      }
      // ... use createResult.data
