// ── Guard for Prisma errors ───────────────────────────────────────────────────
function isPrismaError(error: unknown): error is Error & { code?: string } {
  return error instanceof Error && "code" in error;
}

// Usage:
catch (error) {
  if (isPrismaError(error)) {
    if (error.message.includes("P2002")) {
      return json({ error: "Slug already taken" }, { status: 409 });
    }
  }
  return json({ error: "Database error" }, { status: 500 });
}

// ── Guard for fetch Response errors ──────────────────────────────────────────
function isResponse(value: unknown): value is Response {
  return value instanceof Response;
}

// In loader:
catch (error) {
  if (isResponse(error)) throw error;  // Re-throw auth redirects
  throw json({ error: "Failed to load" }, { status: 500 });
}

// ── Guard for loader data shape ───────────────────────────────────────────────
function hasError(data: unknown): data is { error: string } {
  return (
    typeof data === "object" &&
    data !== null &&
    "error" in data &&
    typeof (data as { error: unknown }).error === "string"
  );
}
