## GENERIC UTILITY TYPES

```typescript
// app/utils/helpers.ts

// Safe JSON parse with generic type
function parseSafe<T>(str: string, fallback: T): T {
  try { return JSON.parse(str) as T; }
  catch { return fallback; }
}

// Branded types for IDs (prevent mix-ups)
type QuizId = string & { readonly _brand: "QuizId" };
type ShopDomain = string & { readonly _brand: "ShopDomain" };

function asQuizId(id: string): QuizId {
  return id as QuizId;
}

// Awaited return type utility
type ResolvedReturnType<T extends (...args: unknown[]) => Promise<unknown>> =
  Awaited<ReturnType<T>>;

// Loader data type from loader function
type LoaderData = ResolvedReturnType<typeof loader>;
```

