## REACT ROUTER 7 TYPE PATTERNS

```typescript
// Correct type inference for React Router 7:
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useActionData } from "react-router";

export async function loader({ request }: LoaderFunctionArgs) {
  // ...
  return json({ quizzes, total });
}

export async function action({ request }: ActionFunctionArgs) {
  // ...
  return json({ success: true, message: "Done" });
}

// In component — TypeScript infers return types:
export default function Page() {
  const { quizzes } = useLoaderData<typeof loader>();
  // quizzes is properly typed from loader return

  const actionData = useActionData<typeof action>();
  // actionData is typed — including null on initial render
}

