## BILLING SERVICE

```typescript
// app/services/billing.server.ts
import db from "~/db.server";
import { PLAN_LIMITS, PLAN_FEATURES, type PlanId } from "~/utils/constants";
import { json } from "react-router";

// ── Get shop subscription ─────────────────────────────────────────────────────
export async function getSubscription(shop: string) {
  return db.subscription.findUnique({ where: { shop } });
}

// ── Get plan ID (default: free) ───────────────────────────────────────────────
export async function getPlanId(shop: string): Promise<PlanId> {
  const sub = await db.subscription.findUnique({
    where: { shop },
    select: { planId: true, status: true },
  });

  // Cancelled or missing = fall back to free
  if (!sub || sub.status !== "active") return "free";
  return (sub.planId as PlanId) ?? "free";
}

// ── Require minimum plan (throws 403 if not met) ─────────────────────────────
export async function requirePlan(
  shop: string,
  minimumPlan: PlanId
): Promise<void> {
  const planOrder: PlanId[] = ["free", "starter", "pro", "enterprise"];
  const currentPlan = await getPlanId(shop);
  const currentIndex = planOrder.indexOf(currentPlan);
  const requiredIndex = planOrder.indexOf(minimumPlan);

  if (currentIndex < requiredIndex) {
    throw json(
      {
        error: `This feature requires the ${minimumPlan} plan or higher.`,
        requiredPlan: minimumPlan,
        currentPlan,
      },
      { status: 403 }
    );
  }
}

// ── Check quiz creation limit ─────────────────────────────────────────────────
export async function checkQuizLimit(shop: string): Promise<void> {
  const planId = await getPlanId(shop);
  const limit = PLAN_LIMITS[planId].quizLimit;

  if (limit === Infinity) return;  // Unlimited — skip count query

  const count = await db.quiz.count({
    where: { shop, status: { not: "archived" } },
  });

  if (count >= limit) {
    throw json(
      {
        error: `You've reached the ${limit} quiz limit for the ${planId} plan.`,
        currentPlan: planId,
        limit,
        current: count,
      },
      { status: 403 }
    );
  }
}

// ── Check response limit ──────────────────────────────────────────────────────
export async function checkResponseLimit(shop: string): Promise<boolean> {
  const planId = await getPlanId(shop);
  const limit = PLAN_LIMITS[planId].responseLimit;

  if (limit === Infinity) return true;

  const startOfMonth = new Date();
  startOfMonth.setDate(1);
  startOfMonth.setHours(0, 0, 0, 0);

  const count = await db.quizResponse.count({
    where: {
      shop,
      createdAt: { gte: startOfMonth },
    },
  });

  return count < limit;
}

// ── Check if feature is available ────────────────────────────────────────────
export async function hasFeature(
  shop: string,
  feature: keyof typeof PLAN_FEATURES.free
): Promise<boolean> {
  const planId = await getPlanId(shop);
  return PLAN_FEATURES[planId][feature];
}
```

---

## SHOPIFY BILLING API INTEGRATION

```typescript
// app/services/billing.server.ts (continued)

export async function createSubscription(
  admin: AdminApiContext,
  shop: string,
  planId: PlanId
): Promise<string> {
  if (planId === "free") {
    // Downgrade to free — cancel existing subscription
    await db.subscription.upsert({
      where: { shop },
      create: { shop, planId: "free", quizLimit: 1, responseLimit: 100 },
      update: { planId: "free", status: "active", quizLimit: 1, responseLimit: 100 },
    });
    return "/app/billing?success=true";
  }

  const price = PLAN_LIMITS[planId].price;
  const planName = `QuizSnap ${planId.charAt(0).toUpperCase() + planId.slice(1)}`;

  const CREATE_SUBSCRIPTION = `#graphql
    mutation CreateSubscription($name: String!, $lineItems: [AppSubscriptionLineItemInput!]!, $returnUrl: String!) {
      appSubscriptionCreate(
        name: $name
        returnUrl: $returnUrl
        lineItems: $lineItems
        test: ${process.env.NODE_ENV !== "production"}
      ) {
        userErrors { field message }
        confirmationUrl
        appSubscription { id status }
      }
    }
  ` as const;

  const response = await admin.graphql(CREATE_SUBSCRIPTION, {
    variables: {
      name: planName,
      returnUrl: `${process.env.HOST}/app/billing/callback?plan=${planId}&shop=${shop}`,
      lineItems: [{
        plan: {
          appRecurringPricingDetails: {
            price: { amount: price, currencyCode: "USD" },
            interval: "EVERY_30_DAYS",
          },
        },
      }],
    },
  });

  const { appSubscriptionCreate } = response.data;

  if (appSubscriptionCreate.userErrors.length > 0) {
    throw new Error(appSubscriptionCreate.userErrors[0].message);
  }

  return appSubscriptionCreate.confirmationUrl;
}
```

