          </Badge>
          <Text variant="headingMd" as="h3">{featureName}</Text>
          <Text as="p" tone="subdued">
            Upgrade to the {requiredPlan} plan to access {featureName.toLowerCase()}.
          </Text>
        </BlockStack>
        <Button url="/app/billing" variant="primary">
          Upgrade to {requiredPlan.charAt(0).toUpperCase() + requiredPlan.slice(1)}
        </Button>
      </BlockStack>
    </Card>
  );
}

// Usage:
<PlanGate requiredPlan="pro" currentPlan={currentPlan} featureName="A/B Testing">
  <ABTestContent />
</PlanGate>
```

---

## USAGE LIMIT WARNING BANNER

```tsx
// Show when user is approaching their response limit:
function UsageLimitBanner({ shop, responseCount, responseLimit }: {
  shop: string;
  responseCount: number;
  responseLimit: number;
}) {
  const usagePercent = responseLimit > 0 ? (responseCount / responseLimit) * 100 : 0;

  if (usagePercent < 80) return null;

  return (
    <Banner
      tone={usagePercent >= 100 ? "critical" : "warning"}
      title={usagePercent >= 100 ? "Response limit reached" : "Approaching response limit"}
    >
      <BlockStack gap="200">
        <Text as="p">
          You've used {responseCount.toLocaleString()} of {responseLimit.toLocaleString()} monthly responses.
          {usagePercent >= 100 && " New quiz responses will be blocked until you upgrade."}
        </Text>
        <Button url="/app/billing" size="slim" variant="primary">Upgrade plan</Button>
      </BlockStack>
    </Banner>
  );
}
```

---

## BILLING CALLBACK HANDLER

```typescript
// app/routes/app.billing.callback.tsx (or handled in app.billing.tsx loader)
export async function loader({ request }: LoaderFunctionArgs) {
  const { session } = await authenticate.admin(request);
  const url = new URL(request.url);
  const planId = url.searchParams.get("plan") as PlanId | null;
  const chargeId = url.searchParams.get("charge_id");

  if (!planId || !chargeId) {
    return redirect("/app/billing?error=invalid_callback");
  }

  // Verify subscription is active via Shopify API
  // Update our Subscription record
  await db.subscription.upsert({
    where: { shop: session.shop },
    create: {
      shop: session.shop,
      planId,
      shopifySubscriptionId: chargeId,
      status: "active",
      quizLimit: PLAN_LIMITS[planId].quizLimit === Infinity ? 999999 : PLAN_LIMITS[planId].quizLimit,
      responseLimit: PLAN_LIMITS[planId].responseLimit === Infinity ? 999999 : PLAN_LIMITS[planId].responseLimit,
    },
    update: {
      planId,
      shopifySubscriptionId: chargeId,
      status: "active",
    },
  });

  return redirect("/app/billing?success=true");
}
```

---

## SELF-VALIDATION CHECKLIST

- [ ] Plan prices match CLAUDE.md Section 7: $9.99, $29.99, $79.99
- [ ] Response limits match: 100, 1,000, 10,000
- [ ] `requirePlan()` throws `json({}, { status: 403 })` — not throws Error
- [ ] `checkQuizLimit()` called before creating new quiz
- [ ] `PlanGate` component shows upgrade CTA (not broken UI)
- [ ] Shopify billing API uses test mode in non-production
- [ ] Subscription upsert — idempotent (Law 14)
- [ ] Cancelled subscription falls back to "free"

---

## NEVER

- Never hard-code plan prices inline — use `PLAN_LIMITS[planId].price`
- Never show a blank/broken UI for gated features — show PlanGate
- Never use $9, $29, $79 — the prices are $9.99, $29.99, $79.99
- Never trust client-supplied plan ID — always read from database
- Never block quiz submissions due to plan issues — only restrict creation
- Never skip billing check on Pro-only features (A/B testing, export, API)

