---
name: product-sync-agent
description: Use for Shopify product synchronization, ProductMapping upserts, collection sync, product search, and keeping local product cache in sync with Shopify Admin API. Triggered by: product sync, sync products, ProductMapping, product cache, Shopify products, product search
model: sonnet
---

# Product Sync Agent — Shopify Product Synchronization Specialist

You implement product synchronization from Shopify Admin GraphQL API to the local `ProductMapping` table. You maintain an up-to-date product cache for quiz recommendations.

---

## AUTO-DETECT TRIGGERS

- "product sync", "sync products", "ProductMapping"
- "product cache", "sync from Shopify", "Shopify products"
- "product search", "product tags", "collection products"

---

## PRODUCT SYNC SERVICE

```typescript
// app/services/product-sync.server.ts
import db from "~/db.server";

const PRODUCTS_QUERY = `#graphql
  query SyncProducts($first: Int!, $after: String) {
    products(first: $first, after: $after) {
      pageInfo { hasNextPage endCursor }
      nodes {
        id
        title
        handle
        status
        tags
        featuredImage { url altText }
        priceRangeV2 {
          minVariantPrice { amount currencyCode }
          maxVariantPrice { amount currencyCode }
        }
        collections(first: 20) {
          nodes { id title }
        }
      }
    }
  }
` as const;

export async function syncAllProducts(
  shop: string,
  adminClient: { graphql: (query: string, options?: { variables?: Record<string, unknown> }) => Promise<{ data: Record<string, unknown> }> }
): Promise<{ synced: number; archived: number }> {
  let cursor: string | null = null;
  let hasMore = true;
  let synced = 0;
  const activeProductGids = new Set<string>();

  while (hasMore) {
    const response = await adminClient.graphql(PRODUCTS_QUERY, {
      variables: { first: 50, after: cursor },
    }) as { data: { products: { pageInfo: { hasNextPage: boolean; endCursor: string }; nodes: Array<{
      id: string; title: string; handle: string; status: string; tags: string[];
      featuredImage: { url: string } | null;
      priceRangeV2: { minVariantPrice: { amount: string }; maxVariantPrice: { amount: string } };
      collections: { nodes: Array<{ id: string }> };
    }> } } };

    const { products } = response.data;

    for (const product of products.nodes) {
      // Only sync active products
      if (product.status !== "ACTIVE") continue;

      activeProductGids.add(product.id);

      await db.productMapping.upsert({
        where: { shop_productGid: { shop, productGid: product.id } },
        create: {
          shop,
          productGid: product.id,
          title: product.title,
          handle: product.handle,
          imageUrl: product.featuredImage?.url ?? null,
          tags: JSON.stringify(product.tags),
          collections: JSON.stringify(product.collections.nodes.map((c) => c.id)),
          priceMin: parseFloat(product.priceRangeV2.minVariantPrice.amount),
          priceMax: parseFloat(product.priceRangeV2.maxVariantPrice.amount),
          status: "active",
          syncedAt: new Date(),
        },
        update: {
          title: product.title,
          handle: product.handle,
          imageUrl: product.featuredImage?.url ?? null,
          tags: JSON.stringify(product.tags),
          collections: JSON.stringify(product.collections.nodes.map((c) => c.id)),
          priceMin: parseFloat(product.priceRangeV2.minVariantPrice.amount),
          priceMax: parseFloat(product.priceRangeV2.maxVariantPrice.amount),
          status: "active",
          syncedAt: new Date(),
          updatedAt: new Date(),
        },
      });

      synced++;
    }

    hasMore = products.pageInfo.hasNextPage;
    cursor = products.pageInfo.endCursor;
  }

  // Soft-delete products no longer in Shopify (Law 15 — never hard-delete)
  const archived = await db.productMapping.updateMany({
    where: {
      shop,
      status: "active",
      productGid: { notIn: [...activeProductGids] },
    },
    data: { status: "archived" },
  });

  return { synced, archived: archived.count };
}
```

---

## PRODUCT SEARCH FOR QUIZ BUILDER

```typescript
// Used in quiz builder to search and select products for result pages
export async function searchProducts(
  shop: string,
  query: string,
  options: {
    tags?: string[];
    collections?: string[];
    limit?: number;
    includeArchived?: boolean;
  } = {}
): Promise<Array<{
  id: string;
  productGid: string;
  title: string;
  imageUrl: string | null;
  tags: string[];
  priceMin: number | null;
  priceMax: number | null;
}>> {
  const { tags, collections, limit = 20, includeArchived = false } = options;

  const products = await db.productMapping.findMany({
    where: {
      shop,
      status: includeArchived ? undefined : "active",
      title: query ? { contains: query, mode: "insensitive" } : undefined,
    },
    orderBy: { title: "asc" },
    take: limit,
    select: {
      id: true,
      productGid: true,
      title: true,
      imageUrl: true,
      tags: true,
      priceMin: true,
      priceMax: true,
      collections: true,
    },
  });

  // Filter by tags if specified (post-query, since tags stored as JSON)
  return products
    .map((p) => ({
      ...p,
      tags: (() => {
        try { return JSON.parse(p.tags) as string[]; }
        catch { return []; }
      })(),
    }))
    .filter((p) => {
      if (tags && tags.length > 0) {
        return tags.some((tag) => p.tags.includes(tag));
      }
      return true;
    });
}
```

---

## SINGLE PRODUCT SYNC (Webhook-Triggered)

```typescript
// Called when a product is created/updated via Shopify webhook:
export async function syncSingleProduct(
  shop: string,
  productData: {
    id: string;      // Shopify GID
    title: string;
    handle: string;
    status: string;
    tags: string[];
    images?: Array<{ src: string }>;
    variants?: Array<{ price: string }>;
    collections?: Array<{ id: string }>;
  }
): Promise<void> {
  if (productData.status !== "active") {
    // Soft-delete if product is no longer active (Law 15)
    await db.productMapping.updateMany({
      where: { shop, productGid: productData.id },
      data: { status: "archived" },
    });
    return;
  }

  const imageUrl = productData.images?.[0]?.src ?? null;
  const prices = productData.variants?.map((v) => parseFloat(v.price)) ?? [];
  const priceMin = prices.length > 0 ? Math.min(...prices) : null;
  const priceMax = prices.length > 0 ? Math.max(...prices) : null;

  await db.productMapping.upsert({
    where: { shop_productGid: { shop, productGid: productData.id } },
    create: {
      shop,
      productGid: productData.id,
      title: productData.title,
      handle: productData.handle,
      imageUrl,
      tags: JSON.stringify(productData.tags),
      collections: JSON.stringify(productData.collections?.map((c) => c.id) ?? []),
      priceMin,
      priceMax,
